class Solution { public int minimumSemesters(int n,int[][] r) { List<Integer>[]g=new List[n+1];for(int i=1;i<=n;i++)g[i]=new ArrayList<>();int[]d=new int[n+1];for(int[]e:r){g[e[0]].add(e[1]);d[e[1]]++;}ArrayDeque<Integer>q=new ArrayDeque<>();for(int i=1;i<=n;i++)if(d[i]==0)q.add(i);int sem=0,seen=0;while(!q.isEmpty()){sem++;for(int k=q.size();k>0;k--){int u=q.remove();seen++;for(int v:g[u])if(--d[v]==0)q.add(v);}}return seen==n?sem:-1;} }
